def _expect_html_error(recorder, response, aid, label, expected_status):
    recorder.check(
        f'{aid}-no-5xx',
        response.status < 500,
        f'{label} -> HTTP {response.status}（校验类错误不得产生 5xx）',
    )
    recorder.expect_status(
        response,
        expected_status,
        aid=f'{aid}-status',
        detail=f'{label} -> HTTP {response.status}（期望 {expected_status}）',
    )
    doc = _parse_html(response.text)
    error_text = _form_error_text(doc)
    recorder.check(
        f'{aid}-form-error',
        bool(error_text),
        f'{label} 显示可读 form-error，实际 {error_text!r}',
    )
    return doc


def _run_html_move_negative(client, recorder, aid, move_form, move_action, anchor_id, label, value, default_category):
    before = _snapshot(client, recorder, f'{aid}-before')
    if value is _OMIT:
        fields = _form_fields(move_form, omit=('category_id',))
    else:
        fields = _form_fields(move_form, {'category_id': value})
    response = client.post_form(
        move_action, fields, follow_redirects=False, accept='text/html'
    )
    error_doc = _expect_html_error(recorder, response, aid, f'HTML move {label}', 400)
    error_form = _find_record_form(error_doc, 'record-move-form', anchor_id)
    recorder.check(
        f'{aid}-form',
        error_form is not None,
        f'HTML move {label} 错误页保留目标记录 move 表单',
    )
    if error_form is not None:
        retained_record = error_form.value('record_id')
        recorder.check(
            f'{aid}-record-retained',
            retained_record == anchor_id,
            f'HTML move {label} 错误页 record_id={retained_record!r}（期望 {anchor_id!r}）',
        )
        if value is not _OMIT:
            retained_category = error_form.value('category_id')
            recorder.check(
                f'{aid}-category-retained',
                retained_category == value,
                f'HTML move {label} 错误页 category_id={retained_category!r}（期望 {value!r}）',
            )
    after = _snapshot(client, recorder, f'{aid}-after')
    _check_unchanged(recorder, aid, before, after, f'HTML move {label}')
    categories = _fetch_categories(client, recorder, f'{aid}-categories')
    record = _get_record_json(client, recorder, f'{aid}-anchor', anchor_id)
    if record is not None:
        actual = _record_category_name(record, categories)
        recorder.check(
            f'{aid}-anchor-category',
            actual == default_category,
            f'HTML move {label} 后锚点 category={actual!r}（期望 {default_category!r}）',
        )
    return record


