            client, recorder, 'a05-record',
            title=f'A05 记录 {uuid.uuid4().hex[:8]}',
            description=f'A05 描述 {uuid.uuid4().hex[:8]}',
        )
        if not recorder.check(
            'a05-prerequisites',
            bool(target_id) and bool(record_id),
            f'目标归类 id={target_id!r}，记录 id={record_id!r}',
        ):
            return
        doc = _home_page(
            client, recorder, 'a05-home',
            params={'category': common.DEFAULT_CATEGORY},
        )
        move_form = _find_record_form(doc, 'record-move-form', record_id)
        if not recorder.check(
            'a05-move-form',
            move_form is not None,
            f'记录行含 record-move-form（record_id={record_id!r}）',
        ):
