def _a05_across_restart(args, recorder):
    first = common.launch_app(args.app_root, args.data_dir, 0)
    instance_dir = first.instance_dir
    target_name = _unique_category('a05restart')
    target_id = None
    record_id = None
    try:
        client = common.HttpClient(first.base_url)
        try:
            health = client.get('/api/health')
            recorder.expect_status(health, 200, aid='a05-restart-health-status')
            target_id = _create_category_json(
                client, recorder, 'a05-restart-target', target_name
            )
            record_id, _ = _create_record_json(
                client, recorder, 'a05-restart-record',
                title=f'A05 重启记录 {uuid.uuid4().hex[:8]}',
                description=f'A05 重启描述 {uuid.uuid4().hex[:8]}',
            )
            if target_id and record_id:
                doc = _home_page(
                    client, recorder, 'a05-restart-home',
                    params={'category': common.DEFAULT_CATEGORY},
                )
                move_form = _find_record_form(
                    doc, 'record-move-form', record_id
                )
                if recorder.check(
                    'a05-restart-move-form',
                    move_form is not None,
                    f'隔离实例记录行含 record-move-form（record_id={record_id!r}）',
                ):
                    response = client.post_form(
                        _form_path(move_form, '/'),
                        _form_fields(move_form, {'category_id': target_id}),
                        follow_redirects=False,
                        accept='text/html',
                    )
                    page, location = _follow_303(
                        client, recorder, response,
                        'a05-restart-move', expected_path='/',
                    )
                    if page is not None:
                        before_stop = _fetch_bookmarks(
                            client, recorder, 'a05-restart-before-stop',
                            params={'category': target_name},
                        )
                        recorder.check(
                            'a05-restart-before-stop-visible',
                            record_id in _record_ids(before_stop),
                            f'停止前记录 {record_id!r} 已在归类 {target_name!r}',
                        )
        finally:
            client.close()
    finally:
        common.stop_app(first)

    if not recorder.check(
        'a05-restart-prerequisite',
        bool(target_id) and bool(record_id),
        f'隔离实例未提供目标归类或记录（target_id={target_id!r}, record_id={record_id!r}）',
    ):
        return

    second = common.launch_app(
        args.app_root, args.data_dir, 0, instance_dir=instance_dir
    )
    try:
        client = common.HttpClient(second.base_url)
        try:
            categories = _fetch_categories(
                client, recorder, 'a05-restart-categories'
            )
            target = _find_category_by_id(categories, target_id)
            recorder.check(
                'a05-restart-category-id',
                target is not None and _record_id(target) == target_id,
                f'重启后归类 {target_name!r} 的 id 保持 {target_id!r}',
            )
            fetched = _get_record_json(
                client, recorder, 'a05-restart-record-json', record_id
            )
            if fetched is not None:
                actual = _record_category_name(fetched, categories)
                recorder.check(
                    'a05-restart-record-category',
                    actual == target_name,
                    f'重启后记录 category={actual!r}（期望 {target_name!r}）',
                )
            new_doc = _home_page(
                client, recorder, 'a05-restart-html-new',
                params={'category': target_name},
            )
            recorder.check(
                'a05-restart-html-visible',
                record_id in _row_ids(new_doc),
                f'重启后归类 {target_name!r} 的 HTML 列表包含记录 {record_id!r}',
            )
            old_doc = _home_page(
                client, recorder, 'a05-restart-html-old',
                params={'category': common.DEFAULT_CATEGORY},
            )
            recorder.check(
                'a05-restart-html-old-absent',
                record_id not in _row_ids(old_doc),
                f'重启后「{common.DEFAULT_CATEGORY}」不再包含记录 {record_id!r}',
            )
        finally:
            client.close()
    finally:
        common.stop_app(second)


def _case_a05(args, recorder):
