def _check_category_state(client, recorder, prefix, expectations):
    categories = _fetch_categories(
        client, recorder, f'{prefix}-api-categories'
    )
    for label, name, category_id, expected_ids in expectations:
        item = _find_category_by_id(categories, category_id)
        if not isinstance(item, dict):
            item = _find_category_by_name(categories, name)
        count = item.get('count') if isinstance(item, dict) else None
        recorder.check(
            f'{prefix}-api-count-{label}',
            count == len(expected_ids),
            f'归类 {name!r} API count={count!r}（期望活动记录数 {len(expected_ids)}）',
        )
        listed = _fetch_bookmarks(
            client, recorder, f'{prefix}-api-list-{label}',
            params={'category': name},
        )
        actual_ids = _record_ids(listed)
        recorder.check(
            f'{prefix}-api-list-{label}',
