                by_id[str(item['id'])] = str(item['name'])
                names.add(str(item['name']))
    for key in ('category', 'category_name', 'categoryName'):
        value = record.get(key)
        if isinstance(value, str):
            if value in names:
                return value
            if value in by_id:
                return by_id[value]
            return value
        if isinstance(value, dict) and value.get('name') is not None:
            return str(value['name'])
    for key in ('category_id', 'categoryId'):
        value = record.get(key)
        if value is not None and str(value) in by_id:
            return by_id[str(value)]
    return None


def _record_category_id(record):
    if not isinstance(record, dict):
        return None
    for key in ('category_id', 'categoryId'):
        value = record.get(key)
        if value is not None:
            return str(value)
    value = record.get('category')
    if isinstance(value, dict) and value.get('id') is not None:
        return str(value['id'])
    return None


def _category_names(categories):
    return {
        str(item['name']) for item in categories
        if isinstance(item, dict) and item.get('name') is not None
    }


def _category_ids(categories):
    return {
        str(item['id']) for item in categories
        if isinstance(item, dict) and item.get('id') is not None
    }


def _find_category_by_name(categories, name):
    if name is None:
        return None
    target = str(name).casefold()
    for item in categories:
        if isinstance(item, dict) and item.get('name') is not None:
            if str(item['name']).casefold() == target:
                return item
    return None


def _find_category_by_id(categories, category_id):
    if category_id is None:
        return None
    target = str(category_id)
    for item in categories:
        if isinstance(item, dict) and item.get('id') is not None:
            if str(item['id']) == target:
                return item
    return None


def _default_category(categories):
    for item in categories:
        if isinstance(item, dict) and item.get('is_default'):
            return item
    return _find_category_by_name(categories, common.DEFAULT_CATEGORY)


def _error_code(response):
    payload = _safe_json(response)
    if isinstance(payload, dict):
        error = payload.get('error')
        if isinstance(error, dict) and error.get('code') is not None:
            return str(error['code'])
        for key in ('code', 'error_code'):
            if payload.get(key) is not None:
                return str(payload[key])
    return None


