def _a09_across_restart(args, recorder):
    first = common.launch_app(args.app_root, args.data_dir, 0)
    instance_dir = first.instance_dir
    record_id = None
    url = _unique_url('a09-restart')
    title = f'A09 重启标题 {uuid.uuid4().hex[:8]}'
    description = f'A09 重启描述 {uuid.uuid4().hex[:8]}'
    category_name = _unique_category('a09-restart')
    try:
        client = common.HttpClient(first.base_url)
        try:
            health = client.get('/api/health')
            recorder.expect_status(health, 200, aid='a09-restart-health-status')
            _, save_form = _save_form_from_home(
                client, recorder, 'a09-restart-save'
            )
            doc = None
            if save_form is not None:
                response = client.post_form(
                    _form_path(save_form, '/bookmarks/new'),
                    _form_fields(save_form, {
                        'url': url,
                        'title': title,
                        'description': description,
                        'category': category_name,
                    }),
                    follow_redirects=False,
                    accept='text/html',
                )
                page, _ = _follow_303(
                    client, recorder, response, 'a09-restart-save',
                    expected_path='/',
                )
                if page is not None:
                    doc = _parse_html(page.text)
                    row = _row_for_url(doc, url)
                    if row is None:
                        doc = _home_page(
                            client, recorder, 'a09-restart-save-fallback',
