                ):
                    response = client.post_form(
                        _form_path(delete_form, '/'),
                        _form_fields(delete_form),
                        follow_redirects=False,
                        accept='text/html',
                    )
                    page, _ = _follow_303(
                        client, recorder, response, 'a09-restart-delete',
                        expected_path='/', expected_query={'trash': '1'},
                    )
                    if page is not None:
                        trash_doc = _parse_html(page.text)
                        recorder.check(
                            'a09-restart-trash-form-before-stop',
                            _find_record_form(
                                trash_doc, 'record-restore-form', record_id
                            ) is not None,
                            f'停止前 /?trash=1 显示记录 {record_id!r} 的恢复表单',
                        )
                trashed = _fetch_bookmarks(
                    client, recorder, 'a09-restart-trashed-before-stop',
                    params={'include_trashed': 1},
                )
                recorder.check(
                    'a09-restart-soft-deleted-before-stop',
                    record_id in _record_ids(trashed),
                    f'停止前 include_trashed=1 仍包含记录 {record_id!r}',
                )
                default_doc = _home_page(
                    client, recorder, 'a09-restart-excluded-before-stop'
                )
                recorder.check(
                    'a09-restart-excluded-before-stop',
                    record_id not in _row_ids(default_doc),
                    f'停止前默认列表排除已删除记录 {record_id!r}',
