def _case_a10(args, recorder):
    client = common.HttpClient(args.base_url)
    try:
        health = client.get('/api/health')
        recorder.expect_status(health, 200, aid='a10-health-status')

        anchor_url = _unique_url('a10-anchor')
        anchor_title = f'A10 锚点 {uuid.uuid4().hex[:8]}'
        anchor_description = f'A10 锚点描述 {uuid.uuid4().hex[:8]}'
        created = client.post_json(
            '/api/bookmarks',
            {
                'url': anchor_url,
                'title': anchor_title,
                'description': anchor_description,
            },
        )
        recorder.expect_status(created, 201, aid='a10-anchor-create-status')
        anchor_id = _record_id(_extract_record(_safe_json(created)))
        if not recorder.check(
            'a10-anchor-create-id',
            bool(anchor_id),
            f'创建锚点记录返回 id={anchor_id!r}',
        ):
            return

        categories = _fetch_categories(client, recorder, 'a10-api-categories')
        before_state = _snapshot(client, recorder, 'a10-api-before')
        before_record = _get_record_json(
            client, recorder, 'a10-anchor-before', anchor_id
        )
        if before_record is None:
            return

        unknown = f'unknown-{uuid.uuid4().hex[:12]}'
        unknown_get = client.get(_bookmark_path(unknown))
        _check_json_error(
            recorder, unknown_get, 'a10-unknown-get', 404, 'not_found',
            f'GET /api/bookmarks/{unknown}',
        )
        unknown_patch = client.patch_json(
            _bookmark_path(unknown), {'title': 'A10 未知 id'}
        )
        _check_json_error(
            recorder, unknown_patch, 'a10-unknown-patch', 404, 'not_found',
            f'PATCH /api/bookmarks/{unknown}',
        )
        unknown_delete = client.request('DELETE', _bookmark_path(unknown))
        _check_json_error(
            recorder, unknown_delete, 'a10-unknown-delete', 404, 'not_found',
            f'DELETE /api/bookmarks/{unknown}',
        )
        unknown_move = client.post_json(
            _move_path(unknown), {'category': common.DEFAULT_CATEGORY}
        )
        _check_json_error(
            recorder, unknown_move, 'a10-unknown-move', 404, 'not_found',
            f'POST /api/bookmarks/{unknown}/move',
        )

        malformed = (
            ('save', 'POST', '/api/bookmarks', '{"url": '),
            ('patch', 'PATCH', _bookmark_path(anchor_id), '{"title": '),
            ('move', 'POST', _move_path(anchor_id), '{"category": '),
        )
        for label, method, path, body in malformed:
            response = client.request(
                method,
                path,
                data=body,
                headers={'Content-Type': 'application/json'},
            )
            _check_json_error(
                recorder, response, f'a10-malformed-{label}', 400, 'bad_request',
                f'{method} {path} 畸形 JSON',
            )

        after_state = _snapshot(client, recorder, 'a10-api-after')
        _check_unchanged(
            recorder, 'a10-api', before_state, after_state, '未知 id 与畸形 JSON 请求'
        )
        after_record = _get_record_json(
            client, recorder, 'a10-anchor-after', anchor_id
        )
        if after_record is not None:
            recorder.check(
                'a10-anchor-url-unchanged',
                _record_url(after_record) == _record_url(before_record),
                f'锚点 url={_record_url(after_record)!r}（未被修改）',
            )
            recorder.check(
                'a10-anchor-title-unchanged',
                _record_title(after_record) == _record_title(before_record),
                f'锚点 title={_record_title(after_record)!r}（未被修改）',
            )
            recorder.check(
                'a10-anchor-description-unchanged',
                _record_description(after_record) == _record_description(before_record),
                f'锚点 description={_record_description(after_record)!r}（未被修改）',
            )
            recorder.check(
                'a10-anchor-category-unchanged',
                _record_category_name(after_record, categories)
                == _record_category_name(before_record, categories),
                f'锚点 category={_record_category_name(after_record, categories)!r}（未被修改）',
            )

        _, save_form = _save_form_from_home(client, recorder, 'a10-html')
        if save_form is None:
            return
        token = uuid.uuid4().hex[:10]
        bad_url = f'atlas-a10-missing-scheme-{token}'
        corrected_url = _unique_url('a10-corrected')
        html_title = f'A10 表单标题 {token}'
        html_description = f'A10 表单描述 {token}'
        before_html_state = _snapshot(client, recorder, 'a10-html-before')
        before_html_ids = set(before_html_state[1])
        before_html_records = _fetch_bookmarks(
            client, recorder, 'a10-html-before-records',
            params={'include_trashed': 1},
        )
